"use strict";(globalThis.webpackChunkall_maker=globalThis.webpackChunkall_maker||[]).push([[4003],{2163(e,t,a){a.d(t,{A:()=>o});const o=a.p+"assets/images/coffeetable-32214b5adf235c09c51d21e2bd1c469b.jpg"},8453(e,t,a){a.d(t,{R:()=>s,x:()=>l});var o=a(6540);const n={},i=o.createContext(n);function s(e){const t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(i.Provider,{value:t},e.children)}},9122(e,t,a){a.r(t),a.d(t,{assets:()=>d,contentTitle:()=>l,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>r});const o=JSON.parse('{"id":"metalworking/welding/coffee-table","title":"Coffee table","description":"We moved into our new apartment. Had our first kid at the time, so time was short. After full-on renovations, we started equipping our new family abode with furniture. And amidst all the chaos, I noticed that my hand was reaching with a coffee mug for a place adjacent to the couch that did not exist.","source":"@site/docs/metalworking/welding/coffee-table.md","sourceDirName":"metalworking/welding","slug":"/metalworking/welding/coffee-table","permalink":"/docs/metalworking/welding/coffee-table","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":6,"frontMatter":{"sidebar_position":6,"title":"Coffee table","sidebar_label":"Coffee table"},"sidebar":"projectsSidebar","previous":{"title":"Soldered lamp","permalink":"/docs/metalworking/welding/solder-lamp"},"next":{"title":"Wallet","permalink":"/docs/metalworking/welding/wallet"}}');var n=a(4848),i=a(8453);const s={sidebar_position:6,title:"Coffee table",sidebar_label:"Coffee table"},l=void 0,d={},r=[{value:"Idea",id:"idea",level:2},{value:"Challenge",id:"challenge",level:2},{value:"Outcome",id:"outcome",level:2},{value:"Learnings",id:"learnings",level:2}];function h(e){const t={h2:"h2",img:"img",li:"li",ol:"ol",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"We moved into our new apartment. Had our first kid at the time, so time was short. After full-on renovations, we started equipping our new family abode with furniture. And amidst all the chaos, I noticed that my hand was reaching with a coffee mug for a place adjacent to the couch that did not exist."}),"\n",(0,n.jsx)(t.p,{children:"It was time to get a coffee table."}),"\n",(0,n.jsx)(t.h2,{id:"idea",children:"Idea"}),"\n",(0,n.jsx)(t.p,{children:"My designs at the time relied heavily on thousands of Pinterests images I saved while late-night doom-scrolling. I knew I wanted it to be out of metal, but not completely because I did not want a rickety-rackety noise sounding off every time I put the mug down."}),"\n",(0,n.jsx)(t.p,{children:"I found some leftover oak hardwood floor from the renovations, so I decided to use that as the top. And I kind of liked those little cube, welded coffee tables I saw online."}),"\n",(0,n.jsx)(t.h2,{id:"challenge",children:"Challenge"}),"\n",(0,n.jsx)(t.p,{children:"Since I decided to weld a perfect cube, but had square pipes that were 2 by 3 centimeters at the cross-section, I had to plan a bit. After consulting YouTube, I decided to expose the 3cm thick side at the top and the bottom, and then simply make the vertical pipes parallel when looked from a side."}),"\n",(0,n.jsx)(t.p,{children:"The task breakdown was:"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsx)(t.li,{children:"Make a jig to weld a metal cube."}),"\n",(0,n.jsx)(t.li,{children:"Deal with warps and the weld splatter."}),"\n",(0,n.jsx)(t.li,{children:"Make a wooden top, sand and protect the wood."}),"\n",(0,n.jsx)(t.li,{children:"Fix the top inside the cube."}),"\n"]}),"\n",(0,n.jsx)(t.h2,{id:"outcome",children:"Outcome"}),"\n",(0,n.jsx)(t.p,{children:"Wouldn't you know it, metal bends when heated! The pipes I used were industrial made and drawn out under a lot of pressure. These don't always have identical consistency across their length and when heated they twist and warp."}),"\n",(0,n.jsx)(t.p,{children:"So I used some L-shaped profiles to first weld a jig that I could use as a template. Then I used metal clamps to fix the pipes into a perfect cube shape. I tack-welded the cube into place, and started working on my main structural welds, one by one. I realigned the structure after every warp with a hammer."}),"\n",(0,n.jsx)(t.p,{children:'In the end I used an angle grinder to fix the welds so the metal does not protrude anywhere. Then used a wire brush to smooth it over, and decided to leave it unpainted. It retained the "industrial" look that the internet assured me everybody liked.'}),"\n",(0,n.jsx)(t.p,{children:"Finally, glued the hardwood floor pieces wogether and cut them to the exact shape of the top. Once it fit flush, I realized that I had no plan to actually attach the wood. I quickly cut two strips out of a metal sheet, sanded them, and drilled the holes. Then, I welded them on the bottom part of the top pipes so I can use the holes to attach the top with self-drilling screws. Once the top was perfectly level, I welded the strips and screwed it in from below."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.img,{alt:"Coffee table",src:a(2163).A+"",width:"5312",height:"2988"})}),"\n",(0,n.jsx)(t.h2,{id:"learnings",children:"Learnings"}),"\n",(0,n.jsx)(t.p,{children:"Out of all the projects I had made by that time, I thought that the coffee table was the most successful. It's still in use to this day. By then, I had already practiced welding a lot, so I used to joke that you could drop this table from the building and the welds would not budge."}),"\n",(0,n.jsx)(t.p,{children:"The sanding and the transparent paintwork were also satisfactory, and there's still no rust to this day."}),"\n",(0,n.jsx)(t.p,{children:"The biggest lesson from this project was that I could make my own jigs and welding setups to be reused for the following projects. Kind of how you see mostly custom-made tools all across blacksmithing workshops. And they did end up useful for the years to come."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}}}]);